WITH UserVotes AS (SELECT UserId, SUM(CASE WHEN VoteTypeId = 2 THEN 1 ELSE 0 END) AS Upvotes, SUM(CASE WHEN VoteTypeId = 3 THEN 1 ELSE 0 END) AS Downvotes FROM Votes GROUP BY UserId), PostStats AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, COALESCE(v.Upvotes, 0) AS TotalUpvotes, COALESCE(v.Downvotes, 0) AS TotalDownvotes, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS RecentPostRank FROM Posts AS p LEFT JOIN UserVotes AS v ON p.OwnerUserId = v.UserId), ClosedPosts AS (SELECT ph.PostId, ph.CreationDate, GROUP_CONCAT(CASE WHEN ph.PostHistoryTypeId = 10 THEN cr.Name END, ', ') AS CloseReasons, COUNT(*) AS CloseCount FROM PostHistory AS ph LEFT JOIN CloseReasonTypes AS cr ON ph.Comment = CAST(cr.Id AS Nullable(String)) WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId, ph.CreationDate) SELECT ps.PostId, ps.Title, ps.CreationDate, ps.Score, ps.TotalUpvotes, ps.TotalDownvotes, cl.CloseReasons, cl.CloseCount FROM PostStats AS ps LEFT JOIN ClosedPosts AS cl ON ps.PostId = cl.PostId WHERE ps.RecentPostRank <= 5 ORDER BY ps.Score DESC NULLS FIRST, ps.CreationDate DESC NULLS FIRST FETCH FIRST 100 ROWS ONLY